#!/usr/bin/env python3
"""Bit-exact / deterministic replay helpers: pin matrix + artifact compare."""
from __future__ import annotations
import hashlib
import json
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional


def pin_matrix() -> Dict[str, Any]:
    return {
        "python": sys.version.split()[0],
        "platform": sys.platform,
        "hash_seed_note": "PYTHONHASHSEED=0 recommended for stable hashing",
    }


def hash_file(path: Path) -> str:
    h = hashlib.sha256()
    h.update(path.read_bytes())
    return h.hexdigest()


def compare_runs(run_a: str, run_b: str, rel_paths: Optional[List[str]] = None) -> Dict[str, Any]:
    a, b = Path(run_a), Path(run_b)
    rel_paths = rel_paths or [
        "reports/run_summary.json",
        "audits/audit_results.json",
        "hashes/merkle.json",
    ]
    diffs = []
    for rel in rel_paths:
        pa, pb = a / rel, b / rel
        if not pa.exists() or not pb.exists():
            diffs.append({"path": rel, "status": "missing_side"})
            continue
        ha, hb = hash_file(pa), hash_file(pb)
        if ha != hb:
            diffs.append({"path": rel, "status": "mismatch", "a": ha[:12], "b": hb[:12]})
    return {
        "ok": len(diffs) == 0,
        "n_compared": len(rel_paths),
        "diffs": diffs,
        "pin_matrix": pin_matrix(),
    }


def write_pin(run_dir: str) -> Path:
    path = Path(run_dir) / "hashes" / "pin_matrix.json"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(pin_matrix(), indent=2))
    return path

