#!/usr/bin/env python3
"""Cross-run index over verification_ledger.jsonl files under artifacts/."""
from __future__ import annotations
import json
from pathlib import Path
from typing import Any, Dict, List, Optional


def find_ledgers(root: str = "artifacts") -> List[Path]:
    root_p = Path(root)
    if not root_p.exists():
        return []
    return sorted(root_p.rglob("verification_ledger.jsonl")) + sorted(
        root_p.rglob("*_ledger.jsonl")
    )


def load_entries(paths: Optional[List[Path]] = None, root: str = "artifacts") -> List[Dict[str, Any]]:
    paths = paths or find_ledgers(root)
    entries = []
    for p in paths:
        try:
            with open(p, encoding="utf-8") as f:
                for i, line in enumerate(f):
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        rec = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    rec["_ledger_path"] = str(p)
                    rec["_line"] = i + 1
                    entries.append(rec)
        except OSError:
            continue
    return entries


def search(
    query: str,
    root: str = "artifacts",
    event_type: Optional[str] = None,
    limit: int = 50,
) -> List[Dict[str, Any]]:
    q = query.lower().strip()
    out = []
    for rec in load_entries(root=root):
        if event_type and rec.get("event_type") != event_type:
            continue
        blob = json.dumps(rec, default=str).lower()
        if q in blob or all(tok in blob for tok in q.split()):
            out.append(rec)
        if len(out) >= limit:
            break
    return out


def summary(root: str = "artifacts") -> Dict[str, Any]:
    entries = load_entries(root=root)
    by_type: Dict[str, int] = {}
    for e in entries:
        t = e.get("event_type") or "unknown"
        by_type[t] = by_type.get(t, 0) + 1
    return {
        "n_ledgers": len(find_ledgers(root)),
        "n_entries": len(entries),
        "by_event_type": by_type,
        "ledger_paths": [str(p) for p in find_ledgers(root)],
    }


if __name__ == "__main__":
    print(json.dumps(summary(), indent=2))

